import * as T from './vendor/three.js';
export function createCar(o,style){const root=new T.Group(),paint=new T.MeshStandardMaterial({color:o.color,roughness:.55,flatShading:style.surface!=='smooth'}),dark=new T.MeshStandardMaterial({color:'#202a35',roughness:.8}),glass=new T.MeshStandardMaterial({color:'#7ba0b9',roughness:.35}),rubber=new T.MeshStandardMaterial({color:'#171a20',roughness:1}),wheels=[];function box(w,h,d,mat,x,y,z){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;root.add(m);return m}box(1.7,.45,3,paint,0,-.13,0);box(1.35,.5,1.4,glass,0,.28,.15);box(1.4,.08,1.45,paint,0,.57,.15);box(1.7,.16,.16,dark,0,-.28,-1.48);box(1.7,.16,.16,dark,0,-.28,1.48);const lights=new T.MeshStandardMaterial({color:'#fff3bf',emissive:'#c6b477',emissiveIntensity:.3});for(const x of[-.6,.6])box(.32,.12,.05,lights,x,-.04,-1.52);for(const x of[-.88,.88])for(const z of[-.95,.95]){const wheel=new T.Mesh(new T.CylinderGeometry(.32,.32,.22,style.surface==='lowpoly'?10:24),rubber);wheel.rotation.z=Math.PI/2;wheel.position.set(x,-.32,z);wheel.castShadow=true;root.add(wheel);wheels.push(wheel)}root.scale.set(o.w/1.9,o.h/1.2,o.depth/3.2);root.userData.animate=(time,speed)=>{for(const w of wheels)w.rotation.x=time*(speed||0)*2};return root}
